function sanitizeName(value){const text=String(value??'').replace(/[\u0000-\u001f\u007f]/g,'').trim();return(text||'玩家').slice(0,12);}function requestedNameValid(name){return !/\d$/.test(String(name||''));}function uniquePlayerName(players,base){const used=new Set(Object.values(players||{}).map(p=>String(p?.name||'')));if(!used.has(base))return base;for(let n=2;n<=99;n++){const suffix=String(n),stem=[...base].slice(0,Math.max(1,12-[...suffix].length)).join(''),candidate=stem+suffix;if(!used.has(candidate))return candidate;}return '玩家'+crypto.randomUUID().replace(/-/g,'').slice(0,4);}
