function randomInt(min,max){const b=new Uint32Array(1);crypto.getRandomValues(b);return min+(b[0]%(max-min+1));}
function normalizeSettings(raw={},base=DEFAULT_SETTINGS){const legacy=raw.normalImpostors===undefined&&(raw.morphers!==undefined||raw.cloakers!==undefined);let normalImpostors=clampInt(raw.normalImpostors,0,5,legacy?0:Number(base.normalImpostors??base.impostors??1)),shapeshifters=clampInt(raw.shapeshifters??raw.morphers,0,5,Number(base.shapeshifters??base.morphers??0)),phantoms=clampInt(raw.phantoms??raw.cloakers,0,5,Number(base.phantoms??base.cloakers??0)),vipers=clampInt(raw.vipers,0,5,Number(base.vipers??0));if(normalImpostors+shapeshifters+phantoms+vipers<1)normalImpostors=1;const impostors=normalImpostors+shapeshifters+phantoms+vipers;return{normalImpostors,shapeshifters,phantoms,vipers,impostors,engineers:clampInt(raw.engineers,0,5,base.engineers??0),scientists:clampInt(raw.scientists,0,5,base.scientists??0),trackers:clampInt(raw.trackers,0,5,base.trackers??0),noisemakers:clampInt(raw.noisemakers,0,5,base.noisemakers??0),detectives:clampInt(raw.detectives,0,5,base.detectives??0),guardianAngels:clampInt(raw.guardianAngels,0,5,base.guardianAngels??0),tasksPerCrew:clampInt(raw.tasksPerCrew,2,6,base.tasksPerCrew),moveSpeed:Math.round(clamp(Number(raw.moveSpeed)||base.moveSpeed,3.45,13.8)*100)/100,killCooldown:clampInt(raw.killCooldown,10,60,base.killCooldown),discussion:clampInt(raw.discussion,0,90,base.discussion),voting:clampInt(raw.voting,15,180,base.voting),emergencyMeetings:clampInt(raw.emergencyMeetings,0,5,base.emergencyMeetings),sabotageCooldown:clampInt(raw.sabotageCooldown,10,60,base.sabotageCooldown),confirmEjects:typeof raw.confirmEjects==='boolean'?raw.confirmEjects:!!base.confirmEjects};}
function buildMap(){const map=new Uint8Array(MAP_SIZE*MAP_SIZE),setWall=(x,y,v=1)=>{if(x>=0&&x<MAP_SIZE&&y>=0&&y<MAP_SIZE)map[y*MAP_SIZE+x]=v;};for(let i=0;i<MAP_SIZE;i++){setWall(i,0);setWall(i,MAP_SIZE-1);setWall(0,i);setWall(MAP_SIZE-1,i);}const lines=[25,50,75,100,125];lines.forEach((x,li)=>{for(let y=1;y<MAP_SIZE-1;y++){const sector=Math.floor(y/25),local=y%25,ds=((sector+li)%2===0)?6:16;if(local<ds||local>ds+2)setWall(x,y);}});lines.forEach((y,li)=>{for(let x=1;x<MAP_SIZE-1;x++){const sector=Math.floor(x/25),local=x%25,ds=((sector+li+1)%2===0)?6:16;if(local<ds||local>ds+2)setWall(x,y);}});for(let sy=0;sy<6;sy++)for(let sx=0;sx<6;sx++){if(sx===3&&sy===3)continue;if((sx+sy)%2!==0)continue;const cx=sx*25+13,cy=sy*25+13,h=((sx*3+sy)%2)===0,w=h?5:2,hh=h?2:5;for(let oy=-Math.floor(hh/2);oy<=Math.floor(hh/2);oy++)for(let ox=-Math.floor(w/2);ox<=Math.floor(w/2);ox++)setWall(cx+ox,cy+oy);}for(let y=70;y<=80;y++)for(let x=70;x<=80;x++)setWall(x,y,0);for(const o of [...OBJECT_DEFS,...VENT_DEFS]){const cx=Math.floor(o.x),cy=Math.floor(o.y);for(let y=cy-1;y<=cy+1;y++)for(let x=cx-1;x<=cx+1;x++)setWall(x,y,0);}return map;}
const MAP_DATA=buildMap();
function isWallCell(c,r){if(c<0||r<0||c>=MAP_SIZE||r>=MAP_SIZE)return true;return MAP_DATA[r*MAP_SIZE+c]===1;}
function isDoorCell(c,r){return DOOR_CELL_SET.has(`${c},${r}`);}
function circleHitsWall(x,y,r=PLAYER_RADIUS,doorsClosed=false){const minX=Math.floor(x-r),maxX=Math.floor(x+r),minY=Math.floor(y-r),maxY=Math.floor(y+r);for(let row=minY;row<=maxY;row++)for(let col=minX;col<=maxX;col++){if(!isWallCell(col,row)&&!(doorsClosed&&isDoorCell(col,row)))continue;const nx=clamp(x,col,col+1),ny=clamp(y,row,row+1),dx=x-nx,dy=y-ny;if(dx*dx+dy*dy<r*r)return true;}return false;}
