  broadcastState(){for(const ws of this.ctx.getWebSockets())this.sendStateTo(ws);}
  broadcastVoiceDirectory(){for(const ws of this.ctx.getWebSockets()){const a=ws.deserializeAttachment(),p=a?.playerId?this.players[a.playerId]:null;if(p)jsonSend(ws,{t:'voice_directory',voices:this.voiceDirectory(p)});}}
  nextColor(){const used=new Set(Object.values(this.players).map(p=>p.color));return COLORS.find(c=>!used.has(c))||COLORS[Object.keys(this.players).length%COLORS.length];}
  nextAnimal(){const n=Object.keys(this.players).length;return ANIMALS[n%ANIMALS.length];}
  spawnForIndex(i){const [x,y]=SPAWNS[i%SPAWNS.length];return{x,y};}
  electHost(){const a=Object.values(this.players).filter(p=>p.connected).sort((x,y)=>x.joinedAt-y.joinedAt);this.hostId=a[0]?.id||Object.values(this.players).sort((x,y)=>x.joinedAt-y.joinedAt)[0]?.id||'';} resetIfEmpty(){if(Object.keys(this.players).length)return false;this.initialized=false;this.createdAt=0;this.hostId='';this.bodies=[];this.phase='lobby';this.startedAt=0;this.endedAt=0;this.winner='';this.reason='';this.meeting=null;this.settings={...DEFAULT_SETTINGS};this.sabotage=null;this.sabotageReadyAt=0;this.doorLockUntil=0;return true;} announceHostChange(previousHostId){if(previousHostId===this.hostId)return;const next=this.players[this.hostId];if(next)this.broadcast({t:'notice',text:`房主已自动转让给 ${next.name}`});}
  sendError(ws,code,message,close=true){jsonSend(ws,{t:'error',code,message});if(close)try{ws.close(4000,code);}catch(_){} }
  actionFail(ws,code,message){jsonSend(ws,{t:'action_fail',code,message});}
  assignGuardian(player,now=Date.now()){if(!player||!isCrewRole(player.role)||player.ghostRole==='guardian')return false;const assigned=Object.values(this.players).filter(p=>p.ghostRole==='guardian').length;if(assigned>=Number(this.settings.guardianAngels||0))return false;player.ghostRole='guardian';player.abilityReadyAt=now+5000;return true;}
