  async ejectExpiredEngineers(now=Date.now()){let changed=false;for(const p of Object.values(this.players)){if(p.role==='engineer'&&p.inVent&&p.ventExitAt&&now>=Number(p.ventExitAt)){const v=VENT_DEFS.find(x=>x.id===p.ventId);p.inVent=false;p.ventId='';p.ventExitAt=0;p.ventReadyAt=now+ENGINEER_VENT_COOLDOWN_MS;if(v)p.pos={x:v.x,y:v.y};p.moveSeq=Number(p.moveSeq||0)+1;this.sendTo(p.id,{t:'vent_state',id:p.id,x:p.pos.x,y:p.pos.y,moveSeq:p.moveSeq,inVent:false,ventId:'',ventReadyAt:p.ventReadyAt});this.broadcast({t:'vent_state',id:p.id,x:p.pos.x,y:p.pos.y,moveSeq:p.moveSeq,inVent:false},p.id);changed=true;}}if(changed)await this.persistNow();}
  async killPlayer(killer,targetId,ws){if(this.phase!=='playing'||!isImpostorRole(killer.role)||!killer.alive||killer.inVent){this.actionFail(ws,'kill_unavailable','当前无法击杀');return;}const now=Date.now();if(now<Number(killer.killReadyAt||0)){this.actionFail(ws,'kill_cooldown','击杀冷却中');return;}const target=this.players[targetId];if(!target||!target.connected||!target.alive||target.inVent||target.id===killer.id||isImpostorRole(target.role)){this.actionFail(ws,'kill_target','目标已不可击杀');return;}if(Math.hypot(killer.pos.x-target.pos.x,killer.pos.y-target.pos.y)>1.2||!hasLineOfSight(killer.pos,target.pos,this.doorLockUntil>now)){this.actionFail(ws,'kill_range','目标已离开击杀范围或被墙体阻挡');return;}if(Number(target.protectedUntil||0)>now){killer.killReadyAt=now+5000;jsonSend(ws,{t:'kill_blocked',killReadyAt:killer.killReadyAt});this.sendTo(target.id,{t:'protected_hit'});await this.persistNow();return;}const bodyId=crypto.randomUUID();for(const q of Object.values(this.players)){q.lastCaseId=bodyId;q.lastCaseArea=areaCodeAt(q.pos.x,q.pos.y);}target.alive=false;target.inVent=false;target.ventId='';target.ventExitAt=0;target.protectedUntil=0;target.activeTask=null;this.bodies.push({id:bodyId,playerId:target.id,name:target.name,color:target.color,x:target.pos.x,y:target.pos.y,createdAt:now,dissolveAt:killer.role==='viper'?now+VIPER_DISSOLVE_MS:0});this.assignGuardian(target,now);killer.killReadyAt=now+this.settings.killCooldown*1000;this.sendTo(target.id,{t:'killed',selfState:this.selfState(target)});if(target.role==='noisemaker'){for(const p of Object.values(this.players))if(p.id!==target.id&&isCrewRole(p.role))this.sendTo(p.id,{t:'noisemaker',playerId:target.id,x:target.pos.x,y:target.pos.y,until:now+6000});}jsonSend(ws,{t:'kill_ok',killReadyAt:killer.killReadyAt});this.broadcast({t:'bodies',bodies:this.bodies});this.broadcastState();await this.persistNow();await this.checkWin('kill');await this.scheduleNextAlarm();}
  async reportBody(player,bodyId,ws){if(this.phase!=='playing'||!player.alive||player.inVent){this.actionFail(ws,'report_unavailable','当前无法报告尸体');return;}const body=this.bodies.find(b=>b.id===bodyId);if(!body){this.actionFail(ws,'body_gone','尸体已不存在或已被报告');return;}if(Math.hypot(player.pos.x-body.x,player.pos.y-body.y)>1.7){this.actionFail(ws,'report_range','靠近尸体后重试');return;}await this.startMeeting(player,{bodyId:body.id,reasonText:`${player.name} 报告了 ${body.name} 的尸体`});}
  async callEmergency(player,ws){if(this.phase!=='playing'||!player.alive||player.inVent){this.actionFail(ws,'meeting_unavailable','当前无法召开紧急会议');return;}if(Number(player.emergencyUsed||0)>=this.settings.emergencyMeetings){this.actionFail(ws,'meeting_limit','你的紧急会议次数已用完');return;}if(this.sabotage){this.actionFail(ws,'sabotage_active','破坏期间不能召开紧急会议');return;}const s=OBJECT_DEFS.find(o=>o.id===EMERGENCY_STATION);if(!s||Math.hypot(player.pos.x-s.x,player.pos.y-s.y)>1.6){this.actionFail(ws,'meeting_range','靠近中央控制台后重试');return;}player.emergencyUsed=Number(player.emergencyUsed||0)+1;await this.startMeeting(player,{bodyId:'',reasonText:`${player.name} 召开了紧急会议`});}
  async startMeeting(player,{bodyId='',reasonText=''}){const now=Date.now();this.phase='meeting';this.sabotage=null;this.doorLockUntil=0;this.sabotageReadyAt=now+this.settings.sabotageCooldown*1000;for(const p of Object.values(this.players)){if(p.role==='engineer'&&p.inVent)p.ventReadyAt=now+ENGINEER_VENT_COOLDOWN_MS;p.inVent=false;p.ventId='';p.ventExitAt=0;p.disguiseTargetId='';p.hiddenUntil=0;p.abilityUntil=0;p.activeTask=null;}const discussionEndsAt=now+this.settings.discussion*1000;this.meeting={id:crypto.randomUUID(),stage:this.settings.discussion>0?'discussion':'voting',callerId:player.id,bodyId,reasonText,discussionEndsAt,votingEndsAt:discussionEndsAt+this.settings.voting*1000,votes:{},eligibleVoters:Object.values(this.players).filter(p=>p.alive&&p.connected).length,result:null,resumeAt:0};this.updateMeetingEligibility();await this.persistNow();for(const p of Object.values(this.players))this.sendTo(p.id,{t:'meeting',meeting:publicMeeting(this.meeting,p.id)});this.broadcastState();await this.scheduleNextAlarm();}
  async castVote(player,target){if(this.phase!=='meeting'||!this.meeting||this.meeting.stage!=='voting'||!player.alive||!player.connected)return;const now=Date.now();if(now>=this.meeting.votingEndsAt||this.meeting.votes[player.id])return;if(target!=='skip'&&(!this.players[target]||!this.players[target].alive))return;this.meeting.votes[player.id]=target;const ready=this.updateMeetingEligibility();await this.persistNow();for(const p of Object.values(this.players))this.sendTo(p.id,{t:'meeting',meeting:publicMeeting(this.meeting,p.id)});if(ready)await this.resolveMeeting();}
  async resolveMeeting(){if(this.phase!=='meeting'||!this.meeting||this.meeting.stage!=='voting')return;const votes=this.meeting.votes||{},counts={skip:0};for(const target of Object.values(votes))counts[target]=(counts[target]||0)+1;let top=0,winners=[];for(const [id,n] of Object.entries(counts)){if(id==='skip')continue;if(n>top){top=n;winners=[id];}else if(n===top&&n>0)winners.push(id);}const skip=Number(counts.skip||0),tie=winners.length>1||(winners.length===1&&top===skip&&top>0);let ejected=null;if(winners.length===1&&top>skip)ejected=this.players[winners[0]]||null;const now=Date.now();if(ejected){ejected.alive=false;ejected.inVent=false;ejected.ventId='';ejected.activeTask=null;if(this.assignGuardian(ejected,now))this.sendTo(ejected.id,{t:'guardian_assigned',selfState:this.selfState(ejected)});}let text='无人被放逐。';if(ejected)text=ejected.name+' 被放逐了。'+(this.settings.confirmEjects?(isImpostorRole(ejected.role)?'TA 是内鬼。':'TA 不是内鬼。'):'');else if(tie)text='票数持平，无人被放逐。';else if(skip>0&&skip>=top)text='跳过票占优，无人被放逐。';this.meeting.stage='result';this.meeting.result={text,ejectedId:ejected?ejected.id:'',tie,counts,votes:{...votes}};this.meeting.resumeAt=now+6500;await this.persistNow();for(const p of Object.values(this.players))this.sendTo(p.id,{t:'meeting_result',meeting:publicMeeting(this.meeting,p.id)});this.broadcastState();await this.scheduleNextAlarm();}
