  async startSabotage(player,kind,ws){if(this.phase!=='playing'||!isImpostorRole(player.role)||!player.alive||player.inVent)return;const now=Date.now();if(now<this.sabotageReadyAt){jsonSend(ws,{t:'error',code:'sabotage_cooldown',message:'破坏冷却中'});return;}if(kind==='doors'){if(this.sabotage){jsonSend(ws,{t:'error',code:'sabotage_active',message:'关键破坏进行中，暂时不能封锁门禁'});return;}this.doorLockUntil=now+DOOR_LOCK_MS;this.sabotageReadyAt=now+this.settings.sabotageCooldown*1000;await this.persistNow();this.broadcast({t:'doors',until:this.doorLockUntil});this.broadcastState();await this.scheduleNextAlarm();return;}const d=SABOTAGE_DEFS[kind];if(!d)return;if(this.sabotage){jsonSend(ws,{t:'error',code:'sabotage_active',message:'已有破坏正在进行'});return;}this.sabotage={type:kind,startedAt:now,endsAt:d.durationMs?now+d.durationMs:0,fixedStations:[]};await this.persistNow();this.broadcast({t:'sabotage',sabotage:publicSabotage(this.sabotage)});this.broadcastState();await this.scheduleNextAlarm();}
  async fixSabotage(player,stationId,ws){if(this.phase!=='playing'||!this.sabotage||!player.alive||player.inVent){this.actionFail(ws,'repair_unavailable','当前没有可执行的修复');return;}const d=SABOTAGE_DEFS[this.sabotage.type];if(!d||!d.stations.includes(stationId)||this.sabotage.fixedStations.includes(stationId)){this.actionFail(ws,'repair_done','这个修复点已经完成');return;}const o=OBJECT_DEFS.find(x=>x.id===stationId);if(!o||Math.hypot(player.pos.x-o.x,player.pos.y-o.y)>1.7){this.actionFail(ws,'repair_range','靠近修复点后重试');return;}this.sabotage.fixedStations.push(stationId);const done=d.stations.every(id=>this.sabotage.fixedStations.includes(id));jsonSend(ws,{t:'repair_ok',stationId,done});if(done){const label=d.label;this.sabotage=null;this.sabotageReadyAt=Date.now()+this.settings.sabotageCooldown*1000;await this.persistNow();this.broadcast({t:'sabotage',sabotage:null});this.broadcast({t:'notice',text:`${label} 已修复`});this.broadcastState();await this.scheduleNextAlarm();}else{await this.persistNow();this.broadcast({t:'sabotage',sabotage:publicSabotage(this.sabotage)});this.broadcastState();}}
  async handleVent(player,action,ventId,ws){const engineer=player.role==='engineer',allowed=isImpostorRole(player.role)||engineer;if(this.phase!=='playing'||!allowed||!player.alive){this.actionFail(ws,'vent_unavailable','当前无法使用通风管');return;}const now=Date.now();if(action==='enter'){if(player.inVent){this.actionFail(ws,'vent_state','你已经在通风管中');return;}if(engineer&&now<Number(player.ventReadyAt||0)){this.actionFail(ws,'vent_cooldown','通风管冷却中');return;}const v=VENT_DEFS.find(x=>x.id===ventId);if(!v||Math.hypot(player.pos.x-v.x,player.pos.y-v.y)>1.15){this.actionFail(ws,'vent_range','靠近通风管后重试');return;}player.inVent=true;player.ventId=v.id;player.pos={x:v.x,y:v.y};player.lastMoveAt=now;if(engineer)player.ventExitAt=now+ENGINEER_VENT_MAX_MS;}else if(action==='travel'){if(!player.inVent){this.actionFail(ws,'vent_state','你已不在通风管中');return;}const from=VENT_DEFS.find(x=>x.id===player.ventId),to=VENT_DEFS.find(x=>x.id===ventId);if(!from||!to||!from.links.includes(to.id)){this.actionFail(ws,'vent_route','这个出口当前不可达');return;}player.ventId=to.id;player.pos={x:to.x,y:to.y};player.lastMoveAt=now;}else if(action==='exit'){if(!player.inVent){this.actionFail(ws,'vent_state','你已离开通风管');return;}const v=VENT_DEFS.find(x=>x.id===player.ventId);if(!v){this.actionFail(ws,'vent_state','通风管状态已变化');return;}player.inVent=false;player.ventId='';player.pos={x:v.x,y:v.y};player.lastMoveAt=now;if(engineer){player.ventExitAt=0;player.ventReadyAt=now+ENGINEER_VENT_COOLDOWN_MS;}}else{this.actionFail(ws,'vent_action','未知的通风管操作');return;}player.moveSeq=Number(player.moveSeq||0)+1;await this.persistNow();jsonSend(ws,{t:'vent_state',id:player.id,x:player.pos.x,y:player.pos.y,moveSeq:player.moveSeq,inVent:player.inVent,ventId:player.ventId,ventReadyAt:Number(player.ventReadyAt||0),ventExitAt:Number(player.ventExitAt||0)});this.broadcast({t:'vent_state',id:player.id,x:player.pos.x,y:player.pos.y,moveSeq:player.moveSeq,inVent:player.inVent},player.id);await this.scheduleNextAlarm();}

  async endGame(winner,reason){if(this.phase==='ended')return true;this.phase='ended';this.winner=winner;this.reason=reason;this.endedAt=Date.now();this.meeting=null;this.sabotage=null;this.doorLockUntil=0;await this.persistNow();for(const p of Object.values(this.players))this.sendTo(p.id,{t:'game_over',winner,reason,selfState:this.selfState(p),roles:Object.fromEntries(Object.values(this.players).map(x=>[x.id,x.role]))});await this.scheduleNextAlarm();return true;}
  async checkWin(source){if(this.phase==='lobby'||this.phase==='ended')return false;const alive=Object.values(this.players).filter(p=>p.alive),imps=alive.filter(p=>isImpostorRole(p.role)),crew=alive.filter(p=>isCrewRole(p.role)),tasks=this.taskProgress();if(Object.values(this.players).some(p=>isImpostorRole(p.role))&&imps.length===0)return this.endGame('crewmate','所有内鬼都已被淘汰');if(tasks.taskTotal>0&&tasks.taskDone>=tasks.taskTotal)return this.endGame('crewmate','所有船员任务已经完成');if(imps.length>0&&imps.length>=crew.length&&(source==='kill'||source==='vote'||source==='leave'))return this.endGame('impostor','内鬼人数已经不低于剩余船员');return false;}
  async resetLobby(player){if(player.id!==this.hostId||this.phase!=='ended')return;this.phase='lobby';this.winner='';this.reason='';this.startedAt=0;this.endedAt=0;this.meeting=null;this.bodies=[];this.sabotage=null;this.doorLockUntil=0;this.sabotageReadyAt=0;let i=0;for(const p of Object.values(this.players)){p.role='';p.ghostRole='';p.alive=true;p.tasks=[];p.fakeTasks=[];p.completed=[];p.killReadyAt=0;p.abilityReadyAt=0;p.abilityUntil=0;p.disguiseTargetId='';p.hiddenUntil=0;p.trackedId='';p.trackUntil=0;p.ventReadyAt=0;p.ventExitAt=0;p.protectedUntil=0;p.lastCaseId='';p.lastCaseArea='';p.poisonedBy='';p.poisonEndsAt=0;p.emergencyUsed=0;p.inVent=false;p.ventId='';p.activeTask=null;p.pos=this.spawnForIndex(i++);p.moveSeq=Number(p.moveSeq||0)+1;p.lastMoveAt=Date.now();}await this.persistNow();this.broadcast({t:'lobby_reset',players:this.publicPlayers()});this.broadcastState();await this.scheduleNextAlarm();}

